// MM'S BOUTIQUE - CARRINHO
(function () {
  "use strict";

  const CART_KEY = "mms_boutique_cart";
  const LOGO_DATA_URI = "data:image/png;base64,";

  function getCart() {
    try {
      const data = JSON.parse(localStorage.getItem(CART_KEY) || "[]");
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }

  function saveCart(cart) {
    localStorage.setItem(CART_KEY, JSON.stringify(cart));
    updateCounter();
  }

  function money(value) {
    return Number(value || 0).toLocaleString("pt-BR", {
      style: "currency",
      currency: "BRL"
    });
  }

  function updateCounter() {
    const total = getCart().reduce((sum, item) => sum + Number(item.quantity || 0), 0);
    document.querySelectorAll(".mms-header-count").forEach(el => {
      el.textContent = total;
    });
  }

  function productFromCard(card) {
    const name = card.querySelector("h3")?.textContent.trim();
    const priceText = card.querySelector(".price")?.textContent.trim();
    const image = card.querySelector(".look-photo img")?.src || "";

    if (!name || !priceText) return null;

    const price = Number(
      priceText.replace(/[^\d,]/g, "").replace(/\./g, "").replace(",", ".")
    );

    return {
      id: name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]+/g, "-"),
      name,
      price: Number.isFinite(price) ? price : 0,
      image,
      color: "Única",
      size: "M",
      quantity: 1
    };
  }

  function addToCart(product) {
    const cart = getCart();
    const existing = cart.find(item => item.id === product.id);

    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push(product);
    }

    saveCart(cart);
    toast("Produto adicionado ao carrinho.");
  }

  function connectBuyButtons() {
    document.querySelectorAll(".buy-btn").forEach(button => {
      if (button.dataset.mmsCartReady === "true") return;

      button.dataset.mmsCartReady = "true";

      button.addEventListener("click", function (event) {
        event.preventDefault();

        const card = button.closest(".look-card");
        const product = card ? productFromCard(card) : null;

        if (!product) {
          toast("Não foi possível identificar o produto.");
          return;
        }

        addToCart(product);
      });
    });
  }

  function toast(text) {
    let element = document.getElementById("mms-cart-toast");

    if (!element) {
      element = document.createElement("div");
      element.id = "mms-cart-toast";
      document.body.appendChild(element);
    }

    element.textContent = text;
    element.classList.add("show");

    clearTimeout(window.mmsToastTimer);
    window.mmsToastTimer = setTimeout(() => element.classList.remove("show"), 2200);
  }

  function injectStoreStyle() {
    if (document.getElementById("mms-cart-store-style")) return;

    const style = document.createElement("style");
    style.id = "mms-cart-store-style";
    style.textContent = `
      #mms-cart-toast {
        position: fixed;
        right: 24px;
        bottom: 24px;
        z-index: 99999;
        background: #2E1F18;
        color: #F7F2E6;
        padding: 14px 18px;
        font: 600 12px Manrope, Arial, sans-serif;
        box-shadow: 0 8px 30px rgba(0,0,0,.18);
        opacity: 0;
        transform: translateY(10px);
        pointer-events: none;
        transition: .2s ease;
      }
      #mms-cart-toast.show {
        opacity: 1;
        transform: translateY(0);
      }
    
    
    `;
    document.head.appendChild(style);
  }

  function injectCartStyle() {
    if (document.getElementById("mms-cart-page-style")) return;

    const style = document.createElement("style");
    style.id = "mms-cart-page-style";
    style.textContent = `
  html, body { margin:0; padding:0; }
  :root { --choc:#2E1F18; --cream-2:#EFE6D1; --gold:#D4AF37; }
  #mms-cart-app { min-height:100vh; background:#F7F2E6; color:#2E1F18; font-family:Manrope,Arial,sans-serif; }

      /* ---------- top ticker ---------- */
      .ticker-band{
        background:var(--choc);
        color:var(--cream-2);
        overflow:hidden;
        white-space:nowrap;
        padding:8px 0;
        border-bottom:1px solid rgba(243,235,219,.1);
      }
      .ticker-track{
        display:inline-block;
        animation:scroll 26s linear infinite;
      }
      .ticker-track span{
        display:inline-block;
        padding:0 28px;
        font-size:11.5px;
        letter-spacing:.14em;
        text-transform:uppercase;
        font-weight:600;
      }
      .ticker-track span::after{
        content:"✦";
        margin-left:28px;
        color:var(--gold);
      }
      @keyframes scroll{
        from{ transform:translateX(0); }
        to{ transform:translateX(-50%); }
      }

      .mms-header { min-height:78px; padding:15px 4%; display:flex; align-items:center; justify-content:flex-start; gap:52px; border-bottom:1px solid rgba(46,31,24,.14); background:#F7F2E6; }
      .mms-brand { display:flex; align-items:center; gap:10px; text-decoration:none; color:#2E1F18; }
      .mms-nav { display:flex; align-items:center; gap:30px; }
      .mms-nav a, .mms-actions a { color:#2E1F18; text-decoration:none; font-size:13px; font-weight:600; letter-spacing:.01em; }
      .mms-nav a:hover { color:#107C41; }
      .mms-actions { display:flex; align-items:center; gap:16px; }
      .mms-cart-link { position:relative; color:#2E1F18; text-decoration:none; font-size:20px; }
      .mms-main { max-width:1240px; margin:auto; padding:0 34px 80px; }
      .mms-breadcrumb { padding:28px 0 0; font-size:11px; color:rgba(46,31,24,.5); }
      .mms-breadcrumb a { color:inherit; text-decoration:none; }
      .mms-title { padding:45px 0 35px; border-bottom:1px solid rgba(46,31,24,.14); }
      .mms-eyebrow { font-size:10px; font-weight:800; letter-spacing:.18em; color:#D4AF37; }
      .mms-title h1 { margin:8px 0 0; font:600 clamp(38px,5vw,58px)/1 Georgia,serif; }
      .mms-title p { margin:12px 0 0; font-size:13px; color:rgba(46,31,24,.58); }
      .mms-grid { display:grid; grid-template-columns:minmax(0,1.55fr) minmax(320px,.8fr); gap:58px; padding-top:45px; }
      .mms-items-head { display:flex; justify-content:space-between; padding-bottom:16px; border-bottom:1px solid rgba(46,31,24,.14); font-size:11px; font-weight:700; }
      .mms-items-head button { border:0; border-bottom:1px solid #2E1F18; background:none; font-size:10px; cursor:pointer; }
      .mms-item { display:grid; grid-template-columns:145px 1fr 20px; gap:22px; padding:24px 0; border-bottom:1px solid rgba(46,31,24,.14); }
      .mms-photo { width:145px; aspect-ratio:3/4; background:linear-gradient(145deg,#B8735E,#8C5443); overflow:hidden; }
      .mms-photo img { width:100%; height:100%; object-fit:cover; display:block; }
      .mms-placeholder { height:100%; display:grid; place-items:center; color:#F7F2E6; font:22px Georgia,serif; }
      .mms-info { display:flex; flex-direction:column; justify-content:space-between; padding:4px 0; }
      .mms-info-label { font-size:9px; font-weight:800; letter-spacing:.15em; color:#D4AF37; }
      .mms-info h3 { margin:7px 0 0; font:600 21px Georgia,serif; }
      .mms-info p { margin:6px 0 0; font-size:11px; color:rgba(46,31,24,.55); }
      .mms-bottom { display:flex; justify-content:space-between; align-items:center; margin-top:22px; }
      .mms-bottom strong { color:#8C5443; font-size:15px; }
      .mms-qty { height:36px; display:flex; align-items:center; border:1px solid rgba(46,31,24,.16); }
      .mms-qty button { width:35px; height:34px; border:0; background:transparent; cursor:pointer; font-size:17px; color:#2E1F18; }
      .mms-qty span { width:38px; text-align:center; font-size:11px; font-weight:700; }
      .mms-remove { border:0; background:none; cursor:pointer; font-size:21px; color:rgba(46,31,24,.45); }
      .mms-summary { background:#EFE6D1; border:1px solid rgba(46,31,24,.14); padding:28px; position:sticky; top:100px; }
      .mms-summary h2 { margin:0; padding-bottom:19px; border-bottom:1px solid rgba(46,31,24,.14); font:600 23px Georgia,serif; }
      .mms-line { display:flex; justify-content:space-between; margin-top:13px; font-size:12px; }
      .mms-coupon { margin-top:20px; padding:18px 0; border-top:1px solid rgba(46,31,24,.14); border-bottom:1px solid rgba(46,31,24,.14); }
      .mms-coupon label { display:block; margin-bottom:8px; font-size:10px; font-weight:800; text-transform:uppercase; }
      .mms-coupon-row { display:flex; }
      .mms-coupon input { width:100%; height:39px; border:1px solid rgba(46,31,24,.14); background:#F7F2E6; padding:0 11px; outline:0; }
      .mms-coupon button { border:0; background:#2E1F18; color:#F7F2E6; padding:0 14px; font-size:10px; font-weight:800; text-transform:uppercase; cursor:pointer; }
      .mms-coupon small { display:block; margin-top:7px; font-size:9px; color:rgba(46,31,24,.5); }
      .mms-total { display:flex; justify-content:space-between; align-items:center; padding:21px 0; }
      .mms-total span { font:600 21px Georgia,serif; }
      .mms-total strong { font:600 25px Georgia,serif; color:#8C5443; }
      .mms-checkout { width:100%; height:50px; border:0; background:#0E5C33; color:#F7F2E6; cursor:pointer; font-size:10px; font-weight:800; letter-spacing:.06em; text-transform:uppercase; }
      .mms-continue { display:block; margin-top:18px; text-align:center; color:#2E1F18; font-size:10px; font-weight:700; text-decoration:none; }
      .mms-empty { text-align:center; padding:90px 30px; border:1px dashed rgba(46,31,24,.2); }
      .mms-empty-icon { font-size:38px; color:#107C41; }
      .mms-empty h2 { margin:15px 0 8px; font:600 30px Georgia,serif; }
      .mms-empty p { margin:0 0 22px; font-size:12px; color:rgba(46,31,24,.55); }
      .mms-footer { padding:35px 5%; background:#0E5C33; color:#F7F2E6; display:flex; justify-content:space-between; gap:25px; }
      .mms-footer strong { font:600 18px Georgia,serif; }
      .mms-footer p { margin:5px 0 0; font-size:10px; opacity:.65; }
      .mms-footer span { margin-left:25px; color:#E6CB6E; font-size:9px; font-weight:800; letter-spacing:.08em; }
      @media(max-width:900px){ .mms-nav{display:none}.mms-grid{grid-template-columns:1fr}.mms-summary{position:static} }
      @media(max-width:600px){ .mms-main{padding:0 18px 60px}.mms-header{padding-left:18px;padding-right:18px}.mms-item{grid-template-columns:90px 1fr 18px;gap:13px}.mms-photo{width:90px}.mms-info h3{font-size:16px}.mms-bottom{align-items:flex-end;gap:8px;flex-direction:column}.mms-footer{flex-direction:column}.mms-footer span{margin:0 20px 0 0} }
    `;
    document.head.appendChild(style);
  }

  function renderCart() {
    const root = document.getElementById("mms-cart-app");
    if (!root) return;

    injectCartStyle();

    const cart = getCart();
    const quantity = cart.reduce((sum, item) => sum + item.quantity, 0);
    const subtotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const items = cart.map(item => `
      <article class="mms-item">
        <div class="mms-photo">
          ${item.image
            ? `<img src="${item.image}" alt="${item.name}">`
            : `<div class="mms-placeholder">MM'S</div>`}
        </div>

        <div class="mms-info">
          <div>
            <div class="mms-info-label">MM'S BOUTIQUE</div>
            <h3>${item.name}</h3>
            <p>Cor: ${item.color} · Tamanho: ${item.size}</p>
          </div>

          <div class="mms-bottom">
            <div class="mms-qty">
              <button type="button" data-minus="${item.id}">−</button>
              <span>${item.quantity}</span>
              <button type="button" data-plus="${item.id}">+</button>
            </div>
            <strong>${money(item.price * item.quantity)}</strong>
          </div>
        </div>

        <button type="button" class="mms-remove" data-remove="${item.id}" aria-label="Remover">×</button>
      </article>
    `).join("");

    root.innerHTML = `
      <div class="mms-page">
        <div class="ticker-band">
          <div class="ticker-track">
            <span>NOVIDADES TODA SEMANA</span>
            <span>ENTREGA TODA NATAL E REGIÃO</span>
            <span>LOJA 01 · SANTA LUZIA, 1550 — IGAPÓ</span>
            <span>LOJA 02 · SUPERFÁCIL ATACADO SGA</span>
            <span>NOVIDADES TODA SEMANA</span>
            <span>ENTREGA TODA NATAL E REGIÃO</span>
            <span>LOJA 01 · SANTA LUZIA, 1550 — IGAPÓ</span>
            <span>LOJA 02 · SUPERFÁCIL ATACADO SGA</span>
          </div>
        </div>

        <header class="mms-header">
        <div style="display:flex;align-items:center;gap:12px;">
          <a class="mms-brand" href="mms-boutique-home.html">
            <img src="data:image/png;base64," alt="MM'S Boutique" style="width:44px;height:44px;object-fit:cover;border-radius:50%;"> </a>
        <div class="logo">MM<em>'</em>S <span style="font-weight:400;font-size:15px;">boutique</span></div>
        
          </div>

          <nav class="mms-nav">
            <a href="mms-boutique-home.html">Vestidos</a>
            <a href="mms-boutique-home.html">Conjuntos</a>
            <a href="mms-boutique-home.html">Coleção Nova</a>
            <a href="mms-boutique-home.html">Infantil</a>
            <a href="mms-boutique-home.html">Moda Masc.</a>
            <a href="mms-boutique-home.html">Plus Size</a>
            <a href="mms-boutique-home.html">Acessórios</a>
          </nav>

        
        </header>

        <main class="mms-main">
          <div class="mms-breadcrumb">
            <a href="mms-boutique-home.html">Início</a> &nbsp;›&nbsp; <strong>Carrinho</strong>
          </div>

          <section class="mms-title">
            <span class="mms-eyebrow">MM'S BOUTIQUE</span>
            <h1>Seu carrinho</h1>
            <p>Revise suas escolhas antes de continuar para a finalização.</p>
          </section>

          <section class="mms-grid">
            <div>
              <div class="mms-items-head">
                <span>${quantity} ${quantity === 1 ? "item" : "itens"}</span>
                ${cart.length ? '<button id="mms-clear" type="button">Limpar carrinho</button>' : ""}
              </div>

              ${cart.length ? items : `
                <div class="mms-empty">
                  <div class="mms-empty-icon">♡</div>
                  <h2>Seu carrinho está vazio</h2>
                  <p>Escolha suas peças favoritas e elas aparecerão aqui.</p>
                  <a class="mms-checkout" style="display:inline-flex;width:auto;padding:0 24px;align-items:center;text-decoration:none" href="mms-boutique-home.html">
                    Continuar comprando
                  </a>
                </div>
              `}
            </div>

            ${cart.length ? `
              <aside class="mms-summary">
                <h2>Resumo do pedido</h2>

                <div class="mms-line">
                  <span>Subtotal</span>
                  <strong>${money(subtotal)}</strong>
                </div>

                <div class="mms-line">
                  <span>Entrega</span>
                  <strong>Grátis</strong>
                </div>

                <div class="mms-coupon">
                  <label for="mms-coupon">Cupom de desconto</label>
                  <div class="mms-coupon-row">
                    <input id="mms-coupon" type="text" placeholder="Digite seu cupom">
                    <button id="mms-apply" type="button">Aplicar</button>
                  </div>
                  <small>Exemplo: MMS10</small>
                </div>

                <div class="mms-total">
                  <span>Total</span>
                  <strong>${money(subtotal)}</strong>
                </div>

                <button id="mms-checkout" class="mms-checkout" type="button">
                  Continuar para pagamento →
                </button>

                <a class="mms-continue" href="mms-boutique-home.html">← Continuar comprando</a>
              </aside>
            ` : ""}
          </section>
        </main>

        <footer class="mms-footer">
          <div>
            <strong>MM'S BOUTIQUE</strong>
            <p>Elegância que se veste de você.</p>
          </div>
          <div>
            <span>ENTREGA TODA NATAL E REGIÃO</span>
            <span>ATENDIMENTO VIA WHATSAPP</span>
          </div>
        </footer>
      </div>
    `;

    document.querySelectorAll("[data-plus]").forEach(btn => {
      btn.onclick = () => changeQuantity(btn.dataset.plus, 1);
    });

    document.querySelectorAll("[data-minus]").forEach(btn => {
      btn.onclick = () => changeQuantity(btn.dataset.minus, -1);
    });

    document.querySelectorAll("[data-remove]").forEach(btn => {
      btn.onclick = () => removeItem(btn.dataset.remove);
    });

    document.getElementById("mms-clear")?.addEventListener("click", () => {
      localStorage.removeItem(CART_KEY);
      renderCart();
      updateCounter();
    });

    document.getElementById("mms-apply")?.addEventListener("click", () => {
      const value = document.getElementById("mms-coupon").value.trim().toUpperCase();
      toast(value === "MMS10" ? "Cupom MMS10 aplicado." : "Cupom não encontrado.");
    });

    document.getElementById("mms-checkout")?.addEventListener("click", () => {
      toast("Aqui entra a integração com seu checkout.");
    });
  }

  function changeQuantity(id, amount) {
    const cart = getCart();
    const item = cart.find(product => product.id === id);
    if (!item) return;

    item.quantity += amount;

    const updated = cart.filter(product => product.quantity > 0);
    saveCart(updated);
    renderCart();
  }

  function removeItem(id) {
    saveCart(getCart().filter(item => item.id !== id));
    renderCart();
  }

  function init() {
    injectStoreStyle();
    connectBuyButtons();
    updateCounter();
    renderCart();

    const observer = new MutationObserver(() => {
      connectBuyButtons();
      updateCounter();
    });

    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  window.MMSCart = {
    getItems: getCart,
    add: addToCart,
    clear: () => {
      localStorage.removeItem(CART_KEY);
      updateCounter();
      renderCart();
    }
  };
})();